function getDocExp254(){
  const p=getP254(), c=getC254(), emp=getJ254("giae_chile_empalme_v220"), tie=getJ254("giae_chile_tierra_v230"), exp=getJ254("giae_chile_expediente_v240")?.expediente, norm=getJ254("giae_chile_normativo_v250");
  const tipo=(typeof getTipoDeclaracionSEC253==="function"?getTipoDeclaracionSEC253(p):localStorage.getItem("giae_chile_tipo_sec_v252"))||"TE1";
  const r=getR254(c,emp);
  const ok=[!!p,c.length>0,!!emp,!!tie,!!exp,!!norm,!!tipo].filter(Boolean).length;
  return{
    p,c,emp,tie,exp,norm,tipoSEC:tipo,r,
    proyecto:p?.proyecto?.nombre||exp?.proyectoNombre||"Sin proyecto",
    cliente:p?.cliente?.nombre||exp?.cliente||"Sin cliente",
    rut:p?.cliente?.rutFormateado||p?.cliente?.rut||"Sin RUT",
    direccion:p?.ubicacion?.direccion||exp?.direccion||"Sin dirección",
    comuna:p?.ubicacion?.comuna||exp?.comuna||"",
    region:p?.ubicacion?.region||exp?.region||"",
    dist:emp?.distribuidora||p?.ubicacion?.distribuidora||exp?.distribuidora||"CGE",
    instalador:p?.instalador?.nombre||exp?.instalador||"Sin instalador",
    claseSEC:p?.instalador?.claseSEC||exp?.claseSEC||"Sin clase SEC",
    avance:Math.round(ok/7*100)
  };
}
function getP254(){try{return typeof getProyectoSeguro==="function"?getProyectoSeguro():JSON.parse(localStorage.getItem(STORAGE_KEY)||"null")}catch(e){return null}}
function getC254(){try{return typeof getCargasSeguras==="function"?getCargasSeguras():JSON.parse(localStorage.getItem(CARGAS_KEY)||"[]")}catch(e){return[]}}
function getJ254(k){try{return JSON.parse(localStorage.getItem(k)||"null")}catch(e){return null}}
function getR254(c,emp){
  let r=null;try{if(typeof resumenIngenieria==="function")r=resumenIngenieria()}catch(e){}
  if(r)return r;
  const totalW=(c||[]).reduce((s,x)=>s+Number(x.totalW||(Number(x.cantidad||1)*Number(x.potenciaUnidad||x.potencia||0))||0),0);
  const demandaW=emp?.resumen?.demandaW||(c||[]).reduce((s,x)=>s+Number(x.demandaW||x.totalW||(Number(x.cantidad||1)*Number(x.potenciaUnidad||x.potencia||0))||0),0);
  return{totalW,demandaW,cargas:c};
}
function estadoDocs254(e){
  return[
    {titulo:"Proyecto",ok:!!e.p,detalle:e.proyecto},
    {titulo:"Clasificación SEC",ok:!!e.tipoSEC,detalle:e.tipoSEC},
    {titulo:"Cuadro de carga",ok:e.c.length>0,detalle:e.c.length+" circuitos"},
    {titulo:"Empalme",ok:!!e.emp,detalle:e.emp?.evaluacion?.tipoEmpalme||"Sin empalme"},
    {titulo:"Tierra",ok:!!e.tie,detalle:e.tie?.data?.tipoSistema||"Sin tierra"},
    {titulo:"Carpeta Técnica",ok:!!e.exp,detalle:e.exp?"Guardada":"Pendiente"}
  ];
}
