  return`<div class="doc-print-256"><h1>Presupuesto Técnico Preliminar</h1><p><b>GIAE Chile v3.2.0</b> · Creado por Julio Vera Concha</p><table><tr><th>Proyecto</th><td>${esc256(e.proyecto)}</td></tr><tr><th>Cliente</th><td>${esc256(e.cliente)}</td></tr><tr><th>Dirección</th><td>${esc256(e.direccion)}</td></tr><tr><th>Distribuidora</th><td>${esc256(e.dist)}</td></tr><tr><th>Declaración SEC</th><td>${esc256(e.tipoSEC)}</td></tr><tr><th>Potencia demandada</th><td>${(Number(e.demandaW||0)/1000).toFixed(2)} kW</td></tr></table><h2>Materiales</h2>${renderMaterialesLectura256(p.materiales)}<h2>Resumen</h2>${renderResumenPresupuesto256(p)}<p><b>Nota:</b> presupuesto preliminar editable. Validar precios, cubicación, distancias y condiciones de terreno.</p></div>`;
