function datosInforme260(){
  const p=getJ260("giae_chile_proyecto_v1")||getJ260("giae_chile_proyecto")||null,c=getCargas260(),emp=getJ260("giae_chile_empalme_v220"),tie=getJ260("giae_chile_tierra_v230"),doc=getJ260("giae_chile_documentacion_v254"),pres=getJ260("giae_chile_presupuesto_v256");
  const tipo=(typeof getTipoDeclaracionSEC253==="function"?getTipoDeclaracionSEC253(p):localStorage.getItem("giae_chile_tipo_sec_v252"))||"TE1";
  const ok=[!!p,c.length>0,!!emp,!!tie,!!doc,!!pres].filter(Boolean).length;
  return{p,c,emp,tie,doc,pres,tipoSEC:tipo,avance:Math.round(ok/6*100),proyecto:p?.proyecto?.nombre||"Proyecto sin nombre",cliente:p?.cliente?.nombre||"Cliente no definido",direccion:p?.ubicacion?.direccion||"Dirección no definida",empresa:p?.empresa?.nombre||p?.instalador?.empresa||"Empresa / institución no definida",instalador:p?.instalador?.nombre||"Responsable no definido",distribuidora:emp?.distribuidora||p?.ubicacion?.distribuidora||"Distribuidora no definida",cargas:c.length,potencia:((pres?.expediente?.demandaW||emp?.resumen?.demandaW||0)/1000).toFixed(2)};
}
function getJ260(k){try{return JSON.parse(localStorage.getItem(k)||"null")}catch(e){return null}}
function getCargas260(){try{return typeof getCargasSeguras==="function"?getCargasSeguras():JSON.parse(localStorage.getItem(CARGAS_KEY)||"[]")}catch(e){return[]}}
function estructuraInforme260(ext){let a=[{t:"Portada",d:"Identidad del usuario, empresa o institución. Sin marca GIAE."},{t:"Índice",d:"Estructura automática del documento."},{t:"Introducción",d:"Contexto del trabajo y finalidad."},{t:"Objetivos",d:"Objetivo general y específicos."},{t:"Antecedentes",d:"Cliente, dirección y responsable."},{t:"Desarrollo técnico",d:"Descripción del trabajo."},{t:"Normativa",d:"RIC, DS N°8 e IEC referenciales."},{t:"Conclusiones",d:"Resultado técnico final."}];if(ext==="profesional"||ext==="completo"){a.push({t:"Evidencia fotográfica",d:"Registro visual."},{t:"Mediciones",d:"Tablas de pruebas."},{t:"Recomendaciones",d:"Mejoras futuras."},{t:"Anexos",d:"Respaldo documental."});}return a;}
function valoresInforme260(){return{tipo:val260("infTipo260")||"tecnico",extension:val260("infExtension260")||"medio",perfil:val260("infPerfil260")||"instalador",empresa:val260("infEmpresa260"),logo:val260("infLogo260"),responsable:val260("infResponsable260"),numero:val260("infNumero260"),trabajo:val260("infTrabajo260"),observaciones:val260("infObservaciones260"),mediciones:val260("infMediciones260"),fotos:val260("infFotos260")};}
function val260(id){return document.getElementById(id)?.value||""}
function actualizarVistaInforme260(){const p=document.getElementById("previewInforme260");if(p)p.innerHTML=generarInformeHTML260(datosInforme260(),valoresInforme260());}
function tituloTipo260(t){return {tecnico:"Informe Técnico Profesional",academico:"Informe Académico Técnico",mantencion:"Informe de Mantención",instalacion:"Informe de Instalación",falla:"Informe de Falla o Reparación",puesta:"Informe de Puesta en Servicio",visita:"Informe de Visita Técnica"}[t]||"Informe Técnico";}
function tonoPerfil260(p){return p==="estudiante"?"redacción técnica formativa":p==="empresa"?"redacción corporativa formal":p==="cliente"?"redacción clara para cliente final":"redacción técnica profesional";}
function generarInformeHTML260(base=datosInforme260(),v=valoresInforme260()){
  const e=estructuraInforme260(v.extension||"medio");
  return `<div class="doc-informe-260"><section class="portada-260"><h1>${esc260(tituloTipo260(v.tipo))}</h1><h2>${esc260(base.proyecto)}</h2><p><b>${esc260(v.empresa||base.empresa)}</b></p><p>${v.logo?`Portada / logo institucional: ${esc260(v.logo)}`:"Portada del usuario sin marca GIAE."}</p><p><b>N° informe:</b> ${esc260(v.numero||"Sin número")} · <b>Fecha:</b> ${new Date().toLocaleDateString("es-CL")}</p></section><h2>1. Introducción</h2><p>El presente informe documenta técnicamente el trabajo asociado al proyecto <b>${esc260(base.proyecto)}</b>, ubicado en ${esc260(base.direccion)}. Se utiliza ${esc260(tonoPerfil260(v.perfil))}.</p><h2>2. Antecedentes generales</h2><table><tr><th>Cliente</th><td>${esc260(base.cliente)}</td></tr><tr><th>Responsable</th><td>${esc260(v.responsable||base.instalador)}</td></tr><tr><th>Distribuidora</th><td>${esc260(base.distribuidora)}</td></tr><tr><th>Declaración SEC</th><td>${esc260(base.tipoSEC)}</td></tr><tr><th>Circuitos registrados</th><td>${base.cargas}</td></tr><tr><th>Demanda estimada</th><td>${esc260(base.potencia)} kW</td></tr></table><h2>3. Objetivos</h2><p>Registrar el alcance del trabajo, resumir las condiciones técnicas principales, dejar evidencia de mediciones y observaciones, y preparar un respaldo documental ordenado.</p><h2>4. Trabajo realizado</h2><p>${esc260(v.trabajo||"Pendiente de completar por el usuario. El asistente no inventa información técnica no ingresada.")}</p><h2>5. Desarrollo técnico</h2><p>El análisis considera proyecto activo, cargas, empalme, puesta a tierra, presupuesto y documentación asociada.</p><h2>6. Normativa de referencia</h2><p>Se consideran como referencia los Pliegos Técnicos RIC 1 al RIC 19, el Decreto Supremo N.º 8 y normas IEC aplicables.</p><h2>7. Mediciones</h2><p>${esc260(v.mediciones||"Pendiente de completar con mediciones reales.")}</p><h2>8. Evidencia fotográfica</h2><p>${esc260(v.fotos||"Pendiente de adjuntar o describir fotografías.")}</p><h2>9. Observaciones</h2><p>${esc260(v.observaciones||"Sin observaciones registradas.")}</p><h2>10. Conclusiones</h2><p>Con la información disponible, el proyecto presenta un avance documental de ${base.avance}%. Antes de emitir el informe final se recomienda verificar mediciones, fotografías y cumplimiento normativo.</p><h2>Índice proyectado</h2><ol>${e.map(x=>`<li>${esc260(x.t)} - ${esc260(x.d)}</li>`).join("")}</ol></div>`;
}
