function meiBaseConductores271(){
  return [
    {sec:1.5, iz:15, uso:"Alumbrado y control según condiciones reales"},
    {sec:2.5, iz:21, uso:"Enchufes y circuitos generales según condiciones reales"},
    {sec:4, iz:28, uso:"Alimentadores pequeños según condiciones reales"},
    {sec:6, iz:36, uso:"Alimentadores medianos según condiciones reales"},
    {sec:10, iz:50, uso:"Alimentadores principales según condiciones reales"},
    {sec:16, iz:68, uso:"Alimentadores de mayor demanda según condiciones reales"}
  ];
}
function meiProtecciones271(){
  return [6,10,16,20,25,32,40,50,63];
}
function meiCalcular271(datos){
  const P=Number(datos.potencia)||0;
  const V=Number(datos.tension)||220;
  const fp=Number(datos.fp)||1;
  const fases=datos.fases||"mono";
  const largo=Number(datos.largo)||0;
  const tipo=datos.tipo||"general";
  const falt=[];
  if(!P)falt.push("potencia");
  if(!V)falt.push("tensión");
  if(!largo)falt.push("longitud");
  if(!fp)falt.push("factor de potencia");
  const Ib=fases==="tri" ? P/(Math.sqrt(3)*V*fp) : P/(V*fp);
  const conductor=meiBaseConductores271().find(c=>c.iz>=Ib) || meiBaseConductores271().slice(-1)[0];
  const proteccion=meiProtecciones271().find(a=>a>=Ib && a<=conductor.iz) || meiProtecciones271().find(a=>a>=Ib) || meiProtecciones271().slice(-1)[0];
  const cumpleRelacion=Ib<=proteccion && proteccion<=conductor.iz;
  const caida=meiCaida271(Ib,largo,conductor.sec,fases,V);
  const confianza=falt.length>=3?"baja":falt.length>=1?"media":"alta";
  const recomendaciones=[];
  if(!cumpleRelacion)recomendaciones.push("Revisar combinación conductor/protección porque no cumple la relación Ib ≤ In ≤ Iz.");
  if(caida.porcentaje>3)recomendaciones.push("La caída de tensión estimada supera 3%; revisar sección, longitud o criterio aplicable.");
  if(tipo==="motor")recomendaciones.push("Para motores se debe considerar corriente de partida, curva de protección y características del equipo.");
  if(!recomendaciones.length)recomendaciones.push("No se detectan conflictos preliminares con los datos ingresados.");
  return {P,V,fp,fases,largo,tipo,Ib,conductor,proteccion,cumpleRelacion,caida,confianza,faltantes:falt,recomendaciones};
}
function meiCaida271(Ib,largo,seccion,fases,V){
  const rho=0.0175;
  const factor=fases==="tri"?Math.sqrt(3):2;
  const vd=factor*Ib*largo*rho/seccion;
  const pct=V?vd/V*100:0;
  return {volt:vd,porcentaje:pct};
}
function meiExplicar271(r){
  const faseTxt=r.fases==="tri"?"trifásico":"monofásico";
  const formula=r.fases==="tri"?"Ib = P / (√3 × V × cos φ)":"Ib = P / (V × cos φ)";
  let txt=`Para una carga ${faseTxt} de ${r.P} W se aplica la fórmula ${formula}. La corriente de diseño estimada es ${r.Ib.toFixed(2)} A. `;
  txt+=`Con esa corriente, el motor selecciona preliminarmente un conductor de ${r.conductor.sec} mm² con Iz referencial ${r.conductor.iz} A y una protección de ${r.proteccion} A. `;
  txt+=r.cumpleRelacion?`La relación Ib ≤ In ≤ Iz se cumple de forma preliminar. `:`La relación Ib ≤ In ≤ Iz requiere revisión. `;
  txt+=`La caída de tensión estimada es ${r.caida.porcentaje.toFixed(2)} %. `;
  txt+=`Nivel de confianza: ${r.confianza}. `;
  if(r.faltantes.length)txt+=`Faltan datos que pueden mejorar la precisión: ${r.faltantes.join(", ")}. `;
  txt+=`Esta recomendación no reemplaza la revisión del profesional responsable ni la verificación normativa aplicable.`;
  return txt;
}
