function mniReglas272(){
  return [
    {id:"MNI-IB-IN-IZ",grupo:"Protecciones",ref:["RIC 4","Knowledge Core"],nivel:"critico",texto:"Verificar relación Ib ≤ In ≤ Iz.",eval:function(r){return !!(r&&r.resultado&&r.resultado.cumpleRelacion)},obs:"La protección debe coordinarse con corriente de diseño y capacidad del conductor."},
    {id:"MNI-CAIDA",grupo:"Conductores",ref:["RIC","IEC"],nivel:"advertencia",texto:"Verificar caída de tensión estimada.",eval:function(r){return ((r&&r.resultado&&r.resultado.caida&&r.resultado.caida.porcentaje)||99)<=3},obs:"Si la caída es alta, revisar longitud, sección o criterio aplicable."},
    {id:"MNI-DATOS",grupo:"Datos",ref:["GIE","MEI"],nivel:"advertencia",texto:"Verificar que no existan datos faltantes.",eval:function(r){return ((r&&r.resultado&&r.resultado.faltantes)||[]).length===0},obs:"Si faltan datos, la validación baja su nivel de confianza."},
    {id:"MNI-CONFIANZA",grupo:"Trazabilidad",ref:["GIE"],nivel:"informativo",texto:"Registrar nivel de confianza del MEI.",eval:function(r){return r&&r.resultado&&r.resultado.confianza==="alta"},obs:"La confianza media o baja requiere revisión profesional."},
    {id:"MNI-NORMATIVA",grupo:"Knowledge Core",ref:["GKC"],nivel:"informativo",texto:"Relacionar cálculo con registros normativos disponibles.",eval:function(){return mniKnowledge272().some(function(x){return x.tipo==="Normativa"})},obs:"El Knowledge Core debe contener referencias verificables, no textos protegidos copiados."}
  ];
}
function mniEvaluar272(){
  const mei=mniResultadoMEI272(), reglas=mniReglas272();
  const resultados=reglas.map(function(reg){let ok=false;try{ok=!!reg.eval(mei)}catch(e){}return Object.assign({},reg,{ok:ok});});
  const ok=resultados.filter(function(x){return x.ok}).length;
  const criticos=resultados.filter(function(x){return x.nivel==="critico"&&!x.ok}).length;
  const advertencias=resultados.filter(function(x){return x.nivel==="advertencia"&&!x.ok}).length;
  const porcentaje=Math.round(ok/resultados.length*100);
  const conocimiento=mniKnowledge272(), relacionadas=mniNormasRelacionadas272(mei,conocimiento);
  return {mei:mei,resultados:resultados,criticos:criticos,advertencias:advertencias,porcentaje:porcentaje,conocimiento:conocimiento,relacionadas:relacionadas};
}
function mniNormasRelacionadas272(mei,regs){
  return regs.filter(function(r){
    const txt=(r.titulo+" "+r.grupo+" "+r.tipo+" "+(r.tags||[]).join(" ")+" "+r.contenido).toLowerCase();
    return r.tipo==="Normativa" || txt.includes("proteccion") || txt.includes("protecciones") || txt.includes("conductor") || txt.includes("corriente");
  }).slice(0,8);
}
function mniTextoInforme272(ev){
  ev=ev||mniEvaluar272();
  if(!ev.mei)return "No existe un cálculo MEI guardado. Genere primero un cálculo en el Motor Eléctrico Inteligente.";
  const r=ev.mei.resultado||{};
  let txt="Se realizó una validación normativa preliminar del cálculo eléctrico. ";
  txt+="La corriente de diseño registrada es "+Number(r.Ib||0).toFixed(2)+" A, con conductor sugerido de "+((r.conductor&&r.conductor.sec)||"N/D")+" mm² y protección sugerida de "+(r.proteccion||"N/D")+" A. ";
  txt+="La relación Ib ≤ In ≤ Iz se encuentra "+(r.cumpleRelacion?"cumplida de forma preliminar":"pendiente de revisión")+". ";
  txt+="La caída de tensión estimada es "+Number((r.caida&&r.caida.porcentaje)||0).toFixed(2)+" %. ";
  txt+="El nivel de cumplimiento preliminar del MNI es "+ev.porcentaje+" %. ";
  if(ev.advertencias||ev.criticos)txt+="Existen observaciones que deben ser revisadas por el profesional responsable antes de emitir documentación final. ";
  txt+="Esta validación no reemplaza la aplicación formal de la normativa vigente ni la revisión del instalador o profesional competente.";
  return txt;
}
