function diagEstado273(){
  const funciones=diagFunciones273().map(f=>{
    const existe=typeof window[f.api]==="function";
    return Object.assign({},f,{existe:existe,estado:existe?"ok":(f.critica?"critico":"advertencia")});
  });
  const claves=[
    {k:"giae_chile_proyecto_v1",nombre:"Proyecto"},
    {k:"giae_chile_identidad_v261",nombre:"Identidad"},
    {k:"giae_chile_plantilla_activa_v261",nombre:"Plantilla activa"},
    {k:"giae_chile_motor_redaccion_v262",nombre:"Redacción"},
    {k:"giae_chile_estado_gie_v263",nombre:"Estado GIE"},
    {k:"giae_chile_integridad_v264",nombre:"Integridad"},
    {k:"giae_chile_knowledge_core_v270",nombre:"Knowledge Core"},
    {k:"giae_chile_motor_electrico_inteligente_v271",nombre:"MEI"},
    {k:"giae_chile_motor_normativo_inteligente_v272",nombre:"MNI"}
  ].map(x=>Object.assign({},x,{existe:!!localStorage.getItem(x.k)}));
  const total=funciones.length, ok=funciones.filter(x=>x.existe).length;
  const criticos=funciones.filter(x=>x.estado==="critico").length;
  const advertencias=funciones.filter(x=>x.estado==="advertencia").length;
  return {funciones,claves,total,ok,criticos,advertencias,porcentaje:Math.round(ok/total*100),fecha:new Date().toISOString()};
}
