function escAudit290(v){return String(v??"").replace(/[&<>"']/g,function(m){return {"&":"&amp;","<":"&lt;",">":"&gt;","\"":"&quot;","'":"&#39;"}[m]})}

function smartSource291(){return window.GIAE_SMART_AUDIT_SOURCE_291||[];}
function smartAnalyze291(){
  const src=smartSource291();
  const codeFiles=src.filter(f=>[".js",".html",".css"].includes(f.ext));
  const jsText=src.filter(f=>f.ext===".js").map(f=>f.text).join("\n");
  const functions=[];
  const re=/function\s+([A-Za-z0-9_]+)\s*\(/g;
  let m;
  while((m=re.exec(jsText))!==null){functions.push({name:m[1],index:m.index});}
  const counts={};
  functions.forEach(f=>counts[f.name]=(counts[f.name]||0)+1);
  const duplicates=Object.keys(counts).filter(k=>counts[k]>1).map(k=>({name:k,count:counts[k]}));
  const unused=functions.filter(f=>{
    const pattern=new RegExp("\\b"+f.name+"\\b","g");
    const matches=(jsText.match(pattern)||[]).length;
    return matches<=1 && !f.name.startsWith("render");
  }).map(f=>f.name).slice(0,80);
  const external=[
    {name:"jQuery",hit:/jquery/i.test(jsText)},
    {name:"Bootstrap",hit:/bootstrap/i.test(jsText)},
    {name:"FontAwesome",hit:/fontawesome|fa-/i.test(jsText)},
    {name:"Google Fonts",hit:/fonts\.googleapis|fonts\.gstatic/i.test(jsText)},
    {name:"React",hit:/react/i.test(jsText)},
    {name:"Vue",hit:/vue/i.test(jsText)}
  ].filter(x=>x.hit);
  const resources=src.filter(f=>[".png",".jpg",".jpeg",".svg",".webp",".ico",".woff",".woff2",".ttf",".otf"].includes(f.ext));
  const todos=[];
  src.forEach(f=>{
    if(!f.text)return;
    const lines=f.text.split(/\n/);
    lines.forEach((line,i)=>{if(/TODO|FIXME|pendiente|revisar|license|licencia/i.test(line))todos.push({file:f.file,line:i+1,text:line.trim().slice(0,180)});});
  });
  const modules=[
    ["GIE","gieEvaluar263"],["Integridad","renderIntegridadProyecto264"],["Knowledge Core","gkcRegistros270"],["MEI","meiCalcular271"],["MNI","mniEvaluar272"],["Diagnóstico","renderDiagnosticoGIAE273"],["Control Center","renderControlCenter274"],["GIAE Core","renderCoreFramework275"],["Auditoría","renderAuditoriaLegal290"]
  ].map(x=>({module:x[0],api:x[1],present:jsText.includes("function "+x[1])||jsText.includes(x[1]+"=")||jsText.includes(x[1]+":")}));
  const large=src.filter(f=>f.size>200000).map(f=>({file:f.file,size:f.size}));
  const score=Math.max(0,100-(duplicates.length*3)-(external.length*4)-(resources.length*2)-(unused.length>20?10:0)-(todos.length>30?8:0));
  return {fecha:new Date().toISOString(),files:src.length,codeFiles:codeFiles.length,functions:functions.length,duplicates,unused,external,resources,todos:todos.slice(0,120),modules,large,score};
}
