function inspectorSource310(){return window.GIAE_INSPECTOR_SOURCE_310||window.GIAE_SMART_AUDIT_SOURCE_291||[];}
function inspectorExtraerFunciones310(){
  const js=inspectorSource310().filter(f=>f.ext===".js").map(f=>f.text).join("\n");
  const arr=[], re=/function\s+([A-Za-z0-9_]+)\s*\(([^)]*)\)\s*\{/g; let m;
  while((m=re.exec(js))!==null){
    const start=m.index, name=m[1], args=m[2];
    let i=re.lastIndex, depth=1;
    while(i<js.length && depth>0){ if(js[i]==="{")depth++; if(js[i]==="}")depth--; i++; }
    const body=js.slice(re.lastIndex,i-1);
    const lines=body.split(/\n/).length;
    const complexity=(body.match(/\b(if|for|while|switch|case|catch|\?|&&|\|\|)\b/g)||[]).length+1;
    const calls=[...body.matchAll(/\b([A-Za-z_][A-Za-z0-9_]*)\s*\(/g)].map(x=>x[1]).filter(x=>!["if","for","while","switch","catch","function"].includes(x));
    arr.push({name,args,lines,complexity,calls,body:body.slice(0,2000)});
  }
  return arr;
}
function inspectorSimilitud310(a,b){
  const ta=new Set(String(a||"").replace(/[^A-Za-z0-9_ ]/g," ").split(/\s+/).filter(x=>x.length>3));
  const tb=new Set(String(b||"").replace(/[^A-Za-z0-9_ ]/g," ").split(/\s+/).filter(x=>x.length>3));
  if(!ta.size||!tb.size)return 0;
  const inter=[...ta].filter(x=>tb.has(x)).length;
  return Math.round(inter/Math.max(ta.size,tb.size)*100);
}
function inspectorAnalizar310(){
  const src=inspectorSource310();
  const funcs=inspectorExtraerFunciones310();
  const grandes=funcs.filter(f=>f.lines>80||f.complexity>30).sort((a,b)=>(b.lines+b.complexity)-(a.lines+a.complexity)).slice(0,30);
  const jsAll=src.filter(f=>f.ext===".js").map(f=>f.text).join("\n");
  const muertas=funcs.filter(f=>{
    const count=(jsAll.match(new RegExp("\\b"+f.name+"\\b","g"))||[]).length;
    return count<=1 && !f.name.startsWith("render") && !f.name.startsWith("esc");
  }).slice(0,50);
  const similares=[];
  for(let i=0;i<Math.min(funcs.length,160);i++){
    for(let j=i+1;j<Math.min(funcs.length,160);j++){
      if(funcs[i].name===funcs[j].name)continue;
      const sim=inspectorSimilitud310(funcs[i].body,funcs[j].body);
      if(sim>=70)similares.push({a:funcs[i].name,b:funcs[j].name,sim});
    }
  }
  const llamadas={};
  funcs.forEach(f=>{llamadas[f.name]=Array.from(new Set(f.calls.filter(c=>funcs.some(x=>x.name===c))));});
  const circulares=[];
  Object.keys(llamadas).forEach(a=>{
    llamadas[a].forEach(b=>{ if(llamadas[b] && llamadas[b].includes(a)) circulares.push({a,b}); });
  });
  const modulos=[
    {nombre:"GIE",api:"gieEvaluar263"},{nombre:"Integridad",api:"renderIntegridadProyecto264"},{nombre:"Knowledge Core",api:"gkcRegistros270"},{nombre:"MEI",api:"meiCalcular271"},{nombre:"MNI",api:"mniEvaluar272"},{nombre:"Diagnóstico",api:"renderDiagnosticoGIAE273"},{nombre:"Control Center",api:"renderControlCenter274"},{nombre:"GIAE Core",api:"renderCoreFramework275"},{nombre:"Auditoría",api:"renderAuditoriaUnificada300"}
  ].map(m=>({ ...m, presente:jsAll.includes(m.api), usos:(jsAll.match(new RegExp("\\b"+m.api+"\\b","g"))||[]).length }));
  const filesGrandes=src.filter(f=>f.size>150000).map(f=>({file:f.file,size:f.size}));
  const descuentos = grandes.length*2 + muertas.length + similares.length*3 + circulares.length*4 + filesGrandes.length*3;
  const salud=Math.max(0,100-Math.min(60,descuentos));
  const prioridad=[];
  if(grandes.length)prioridad.push("Dividir funciones grandes o con alta complejidad.");
  if(muertas.length)prioridad.push("Revisar funciones posiblemente sin uso antes de eliminarlas.");
  if(similares.length)prioridad.push("Unificar funciones similares para reducir deuda técnica.");
  if(circulares.length)prioridad.push("Revisar llamadas circulares entre funciones.");
  if(filesGrandes.length)prioridad.push("Separar archivos muy grandes en módulos independientes.");
  if(!prioridad.length)prioridad.push("La arquitectura se ve estable; continuar documentando y probando.");
  return {fecha:new Date().toISOString(),archivos:src.length,funciones:funcs.length,grandes,muertas,similares:similares.slice(0,40),circulares:circulares.slice(0,40),modulos,filesGrandes,salud,prioridad};
}
